$ErrorActionPreference='Stop'
$root=$PSScriptRoot
$review=Join-Path $root 'gemini_candidate_review';New-Item -ItemType Directory -Path $review -ErrorAction Stop|Out-Null
$wait=[Diagnostics.Stopwatch]::StartNew()
while(!(Test-Path -LiteralPath (Join-Path $root 'supervisor_v2\terminal.json'))){if($wait.Elapsed.TotalSeconds-ge180){throw 'supervisor candidate not terminal; no review call'};Start-Sleep -Seconds 2}
$s=Get-Content -Raw -LiteralPath (Join-Path $root 'supervisor_v2\terminal.json')|ConvertFrom-Json
if($s.status-ne'COMPLETE_UNTRUSTED_PENDING_ROOT_ADMISSION'){throw 'supervisor incomplete; no false review'}
$paths=@((Join-Path $root 'TASK_CONTRACTS.json'),(Join-Path $root 'supervisor_v2\contained_supervisor.py'),(Join-Path $root 'supervisor_v2\tests.candidate.py'),(Join-Path $root 'validator_v2\qualification_validator.py'),(Join-Path $root 'validator_v2\tests.candidate.py'),(Join-Path $root 'windows_job.snapshot.py'))
@($paths|ForEach-Object {@{path=$_;sha256=(Get-FileHash -LiteralPath $_ -Algorithm SHA256).Hash}})|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $review 'source_hashes.json')
$schema=@{type='object';properties=@{verdict=@{type='string'};findings=@{type='array';items=@{type='object';properties=@{artifact=@{type='string'};line=@{type='integer'};severity=@{type='string'};exact_source=@{type='string'};reason=@{type='string'};minimal_fix=@{type='string'};discriminating_test=@{type='string'}};required=@('artifact','severity','exact_source','reason','minimal_fix','discriminating_test')}};qualification_limits=@{type='array';items=@{type='string'}}};required=@('verdict','findings','qualification_limits')}|ConvertTo-Json -Depth 14 -Compress
$sp=Join-Path $review 'schema.json';$schema|Set-Content -LiteralPath $sp
$prompt='You are substantive Gemini reviewer in isolated harness providerfactory. Perform actual independent source review of BOTH candidates against exact TASK_CONTRACTS and proven read-only windows_job snapshot. Read ONLY paths below with readonlyfiletools. Do not shell/import/execute tests/processes or edit anything, no secrets/memory/web/globalqueues. Supervisor process-fixture tests are not admitted. Confirm suspended CreateProcess assignmentbeforeResumeThread, explicitdefaultvsKillonclose difference, correct HANDLE/prototypes/inheritance/cleanup/draintypes/cancel/deadline/failure/atomiclogbounds and no fakecompletion/recovery. Validate validator actual-importtests(notstub), unknown/untrustedNOT_CHECKED, canonicalPCIaliases/timestamps/strictbyteclassification, matchingmodel/workloadidentity/actualallocator and singlevs3vs4capacity, numericalfinite trustedartifacts, CPU/shared/policy/P2P/LLM/durabilityfalseclaimsrefuse. Purevalidator cannotauthenticateJSON: externaltrustgate required. Cite exact lines/source; concrete narrowGrokfix+discriminatingtests. Distinguish unsupportedsourceclaims fromactualWindowsexecutionproof. Do not manufacturebugs fromin-orderqueues ormissingruntimeproof. Return ONLYJSON per schema, no planning-only reply. Paths:'+"`n"+($paths-join"`n")
$prompt|Set-Content -LiteralPath (Join-Path $review 'request.txt')
$si=[Diagnostics.ProcessStartInfo]::new('C:\Users\thoma\AppData\Local\agy\bin\agy.exe');$si.WorkingDirectory=$review;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true
foreach($a in @('--model','gemini-3.8-flash-medium','--mode','plan','--sandbox','--new-project','--disable-slash-commands','--output-format','json','--print-timeout','210s','--json-schema',$sp,'--log-file',(Join-Path $review 'provider.log'),'--print',$prompt)){$si.ArgumentList.Add($a)}
$p=[Diagnostics.Process]::new();$p.StartInfo=$si;$clock=[Diagnostics.Stopwatch]::StartNew();$p.Start()|Out-Null
@{pid=$p.Id;model='gemini-3.8-flash-medium';provider_deadline=210;outer_deadline=240;identity='retained Process handle';clock='Stopwatch';credential_saved=$false;native_children=0}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $review 'launch.json')
$ot=$p.StandardOutput.ReadToEndAsync();$et=$p.StandardError.ReadToEndAsync();$killed=$false
while(!$p.WaitForExit(15000)){@{seconds=[math]::Round($clock.Elapsed.TotalSeconds);state='waiting'}|ConvertTo-Json -Compress|Add-Content -LiteralPath (Join-Path $review 'heartbeat.jsonl');if($clock.Elapsed.TotalSeconds-ge240){$p.Kill($true);$killed=$true;break}}
$p.WaitForExit();$stdout=$ot.GetAwaiter().GetResult();$stderr=$et.GetAwaiter().GetResult();$stdout|Set-Content -LiteralPath (Join-Path $review 'stdout.json');$stderr|Set-Content -LiteralPath (Join-Path $review 'stderr.txt');$state='NOT_ACCEPTED'
try{$r=$stdout|ConvertFrom-Json;$u=$r.usage;$answer=$r.response;if($answer-isnot[string]){$answer=$answer|ConvertTo-Json -Depth 25};$parsed=$answer|ConvertFrom-Json;if(!$killed-and$p.ExitCode-eq0-and$null-ne$parsed.findings){$parsed|ConvertTo-Json -Depth 25|Set-Content -LiteralPath (Join-Path $review 'review.json');$state='COMPLETE_REVIEW_PENDING_ADJUDICATION'}}catch{}
@{requested_model='gemini-3.8-flash-medium';status=$state;pid=$p.Id;exit_code=$p.ExitCode;elapsed_seconds=[math]::Round($clock.Elapsed.TotalSeconds,2);outer_killed=$killed;usage=$u;native_children=0}|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $review 'terminal.json')
